package com.example.inventory.processor;

import com.example.inventory.model.StockUpdate;
import com.example.inventory.repository.ProductRepository;
import com.example.inventory.model.Product;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.Optional;

@Component
public class StockUpdateProcessor {

    private static final Logger logger = LoggerFactory.getLogger(StockUpdateProcessor.class);

    @Autowired
    private ProductRepository productRepository;

    public boolean processUpdate(StockUpdate update) {
        logger.info("Processing stock update for SKU: {}", update.getSku());
        Optional<Product> optProduct = productRepository.findBySku(update.getSku());
        if (!optProduct.isPresent()) {
            logger.warn("Product not found for SKU: {}", update.getSku());
            return false;
        }
        Product product = optProduct.get();
        int newQuantity = product.getQuantity() + update.getQuantityChange();
        if (newQuantity < 0) {
            logger.error("Insufficient stock for SKU: {}. Attempted to reduce by {} but only {} available.",
                    update.getSku(), update.getQuantityChange(), product.getQuantity());
            return false;
        }
        product.setQuantity(newQuantity);
        productRepository.save(product);
        logger.info("Stock updated successfully for SKU: {}. New quantity: {}", update.getSku(), newQuantity);
        return true;
    }

    // Other helper methods could be added here in the future.
    // For now this class only contains the processUpdate method.
    // The repository is injected via field injection which sometimes fails
    // in test contexts that don't scan the component fully.
    // Adding proper constructor injection and a post-construct validation
    // will make the class more robust.
}
