)

type Config struct {
    Name        string `json:"name" yaml:"name"`
    Version     string `json:"version" yaml:"version"`
    Description string `json:"description" yaml:"description"`
    Settings    map[string]string `json:"settings" yaml:"settings"`
}

var rootCmd = &cobra.Command{
    Use:   "mycli",
    Short: "A sample CLI tool",
    RunE:  run,
}

func init() {
    rootCmd.PersistentFlags().StringP("config", "c", "", "Path to config file")
    rootCmd.PersistentFlags().StringP("output", "o", "json", "Output format: json or yaml")
    rootCmd.PersistentFlags().BoolP("verbose", "v", false, "Enable verbose logging")
}

func Execute() {
    if err := rootCmd.Execute(); err != nil {
        fmt.Fprintf(os.Stderr, "error: %v\n", err)
        os.Exit(1)
    }
}

func run(cmd *cobra.Command, args []string) error {
    cfgPath, _ := cmd.Flags().GetString("config")
    output, _ := cmd.Flags().GetString("output")
    verbose, _ := cmd.Flags().GetBool("verbose")

    if verbose {
        fmt.Println("Verbose mode enabled")
    }

    if cfgPath == "" {
        return errors.New("config path must be provided")
    }

    absPath, err := filepath.Abs(cfgPath)
    if err != nil {
        return fmt.Errorf("could not resolve config path: %w", err)
    }

    data, err := ioutil.ReadFile(absPath)
    if err != nil {
        return fmt.Errorf("failed to read config file: %w", err)
    }

    var cfg Config
    if strings.HasSuffix(absPath, ".json") {
        if err := json.Unmarshal(data, &cfg); err != nil {
            return fmt.Errorf("invalid JSON config: %w", err)
        }
    } else if strings.HasSuffix(absPath, ".yaml") || strings.HasSuffix(absPath, ".yml") {
        if err := yaml.Unmarshal(data, &cfg); err != nil {
            return fmt.Errorf("invalid YAML config: %w", err)
        }
    } else {
        return errors.New("unsupported config file type; use .json or .yaml")
    }

    // --- Output handling starts here ---
    if output != "json" && output != "yaml" {
        return fmt.Errorf("unsupported output format: %s", output)
    }

    var outBytes []byte
    if output == "json" {
        outBytes, err = json.MarshalIndent(cfg, "", "  ")
        if err != nil {
            return fmt.Errorf("failed to marshal JSON: %w", err)
        }
    } else {
        outBytes, err = yaml.Marshal(cfg)
        if err != nil {
            return fmt.Errorf("failed to marshal YAML: %w", err)
        }
    }

    fmt.Println(string(outBytes))
    // --- Output handling ends here ---

    return nil
}
