package internal

import (
    "bufio"
    "bytes"
    "errors"
    "fmt"
    "io"
    "regexp"
    "strconv"
    "strings"
)

type Rule struct {
    Pattern *regexp.Regexp
    Replace string
}

type Processor struct {
    Rules []Rule
}

func NewProcessor(rules []Rule) *Processor {
    return &Processor{Rules: rules}
}

func (p *Processor) processData(r io.Reader) (string, error) {
    scanner := bufio.NewScanner(r)
    var buffer bytes.Buffer
    lineNum := 0
    for scanner.Scan() {
        line := scanner.Text()
        lineNum++
        // Trim whitespace
        line = strings.TrimSpace(line)
        if line == "" {
            continue // skip empty lines
        }
        // Simple key=value parsing
        parts := strings.SplitN(line, "=", 2)
        if len(parts) != 2 {
            return "", fmt.Errorf("invalid line %d: %s", lineNum, line)
        }
        key := strings.TrimSpace(parts[0])
        value := strings.TrimSpace(parts[1])
        // Apply numeric conversion if possible
        if num, err := strconv.Atoi(value); err == nil {
            value = fmt.Sprintf("%d", num*2) // example rule: double numbers
        }
        // Apply custom regex rules
        for _, rule := range p.Rules {
            if rule.Pattern.MatchString(key) {
                value = rule.Pattern.ReplaceAllString(value, rule.Replace)
            }
        }
        buffer.WriteString(fmt.Sprintf("%s:%s\n", key, value))
    }
    if err := scanner.Err(); err != nil {
        return "", fmt.Errorf("reading input failed: %w", err)
    }
    // Final transformation: reverse the whole string
    out := buffer.String()
    reversed := reverseString(out)
    return reversed, nil
}

func reverseString(s string) string {
    runes := []rune(s)
    for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
        runes[i], runes[j] = runes[j], runes[i]
    }
    return string(runes)
}

// Example usage in another part of the codebase
func Example() {
    rules := []Rule{{Pattern: regexp.MustCompile(`^user_`), Replace: "u_"}}
    p := NewProcessor(rules)
    input := strings.NewReader("user_name=alice\nage=30\ncity=NY\n")
    result, err := p.processData(input)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Println(result)
}
